package io.github.hoangtnedu.java;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class SpringTest {
 @Autowired MockMvc mvc;@Autowired StudentService service;
 @Test void homeAboutAndList()throws Exception{mvc.perform(get("/")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("HoangTN")));mvc.perform(get("/about")).andExpect(status().isOk());mvc.perform(get("/students")).andExpect(status().isOk());}
 @Test  void formValidationAndPersistence()throws Exception{String code="SV"+System.nanoTime();mvc.perform(post("/students/save").param("studentCode","").param("fullName","").param("email","bad").param("className","")).andExpect(status().isOk()).andExpect(model().attributeHasFieldErrors("student","studentCode","fullName","email","className"));mvc.perform(post("/students/save").param("studentCode",code).param("fullName","Demo").param("email","demo@example.com").param("className","JAVA01")).andExpect(status().is3xxRedirection());assertTrue(service.list("Demo").stream().anyMatch(s->s.getStudentCode().equals(code)));mvc.perform(post("/students/save").param("studentCode",code).param("fullName","Other").param("email","demo@example.com").param("className","JAVA01")).andExpect(status().isOk()).andExpect(model().attributeHasFieldErrors("student","studentCode"));}

}